/**
 * Regenerates desktop/icons/icon.icns, the macOS app icon, from assets/icon-only.png — the same
 * flat 1024x1024 icon source that the icons:native and icons:web scripts use.
 *
 * Apple does not round or inset app icons for you: whatever shape is baked into the .icns is what
 * the Dock, Finder, and app switcher show. `tauri icon` only rescales the source, so an icns
 * generated by it renders as a full-bleed square next to every other app's rounded, inset icon.
 * This script bakes in Apple's macOS icon grid instead — an 824x824 squircle centred in a 1024x1024
 * canvas — so the mark lines up with the system icons around it.
 *
 * Only the macOS icon is shaped. The PNGs in desktop/icons and icon.ico stay square, which is correct for
 * Windows and Linux, and are still generated with `tauri icon assets/icon-only.png -o desktop/icons`
 * — run this script afterwards, since that command overwrites icon.icns with an unshaped square.
 */
import { writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import sharp from 'sharp'

const rootDir = resolve(dirname(fileURLToPath(import.meta.url)), '../..')
const sourcePath = resolve(rootDir, 'assets', 'icon-only.png')
const icnsPath = resolve(rootDir, 'desktop', 'icons', 'icon.icns')

/** Width of the full icon canvas, in px. Apple's macOS icon grid is defined at this size. */
const CANVAS = 1024

/** Width of the icon body within the canvas, in px. The remaining 100px per side is Apple's margin. */
const BODY = 824

/**
 * Exponent of the superellipse |x|^n + |y|^n = 1 used for the icon body's outline. The macOS corners are
 * continuous curves rather than circular arcs, which a superellipse approximates closely; n = 5
 * matches the system shape at the sizes an app icon is actually displayed at.
 */
const SQUIRCLE_EXPONENT = 5

/** The icns entries macOS reads, as [OSType, px]. Each holds the icon rendered at that pixel size. */
const icnsEntries = [
  ['icp4', 16],
  ['icp5', 32],
  ['ic11', 32],
  ['ic12', 64],
  ['ic07', 128],
  ['ic13', 256],
  ['ic08', 256],
  ['ic14', 512],
  ['ic09', 512],
  ['ic10', 1024],
]

/** Renders the icon body's superellipse outline as an SVG path centred in a CANVAS x CANVAS square. */
const squirclePath = () => {
  const radius = BODY / 2
  const center = CANVAS / 2
  // Sample one quadrant of the superellipse in polar-ish form, then mirror it into the other three.
  // 128 samples per quadrant keeps the outline smooth well beyond 1024px.
  const samples = 128
  const quadrant = Array.from({ length: samples + 1 }, (_, i) => {
    const angle = (i / samples) * (Math.PI / 2)
    const x = Math.cos(angle) ** (2 / SQUIRCLE_EXPONENT)
    const y = Math.sin(angle) ** (2 / SQUIRCLE_EXPONENT)
    return [x, y]
  })
  const points = [
    ...quadrant.map(([x, y]) => [x, y]),
    ...quadrant.toReversed().map(([x, y]) => [-x, y]),
    ...quadrant.map(([x, y]) => [-x, -y]),
    ...quadrant.toReversed().map(([x, y]) => [x, -y]),
  ]
  const coords = points.map(([x, y]) => `${center + x * radius},${center + y * radius}`)
  return `M${coords.join('L')}Z`
}

/** Renders the source icon at full canvas size, inset and clipped to the macOS icon shape. */
const renderMacIcon = async () => {
  const mask = Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${CANVAS}" height="${CANVAS}"><path d="${squirclePath()}" fill="#fff"/></svg>`,
  )
  const body = await sharp(sourcePath).resize(BODY, BODY).toBuffer()
  return sharp({ create: { width: CANVAS, height: CANVAS, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } } })
    .composite([
      { input: body, top: (CANVAS - BODY) / 2, left: (CANVAS - BODY) / 2 },
      { input: mask, blend: 'dest-in' },
    ])
    .png()
    .toBuffer()
}

/** Packs PNG-encoded icons into an icns container. */
const packIcns = entries => {
  const chunks = entries.map(([ostype, png]) => {
    const header = Buffer.alloc(8)
    header.write(ostype, 0, 'ascii')
    header.writeUInt32BE(png.length + 8, 4)
    return Buffer.concat([header, png])
  })
  const body = Buffer.concat(chunks)
  const header = Buffer.alloc(8)
  header.write('icns', 0, 'ascii')
  header.writeUInt32BE(body.length + 8, 4)
  return Buffer.concat([header, body])
}

const icon = await renderMacIcon()
const packed = packIcns(
  await Promise.all(
    icnsEntries.map(async ([ostype, size]) => [
      ostype,
      size === CANVAS ? icon : await sharp(icon).resize(size, size).png().toBuffer(),
    ]),
  ),
)
await writeFile(icnsPath, packed)
console.info(`Wrote desktop/icons/icon.icns (${icnsEntries.map(([, size]) => size).join(', ')}px)`)
